launch-switches.sourceCode:
// The launch switches: each one needs a restart (pixi run pick, or pixi run sim ... name:=value).
// Shown in the cockpit's Table panel. It runs on each /diagnostics message, so it shows
// whenever something is connected. Nothing here talks to the car.
import { Input } from "./types";

export const inputs = ["/diagnostics"];
export const output = "/studio_script/launch_switches";

type Switch = { switch: string; what: string; values: string };
type Output = { restart: string; switches: Switch[] };

const switches: Switch[] = [
  { switch: "planner:=", what: "Nav2's planner", values: "lattice (default), hybrid; trials: smac2d, navfn, theta_star" },
  { switch: "tracker:=", what: "the path follower (the panel above swaps it live)", values: "none (default: MPPI), pure_pursuit, stanley, lqr, mpc, mpc_full" },
  { switch: "voxels:=", what: "Nav2 sees the lidar as 0.25 m cubes", values: "false (default), true" },
  { switch: "amcl:=", what: "stock AMCL beside the EKF, scored only (test_lot)", values: "false (default), true" },
  { switch: "ndt:=", what: "NDT on the lidar map, scored only (test_lot)", values: "false (default), true" },
  { switch: "ndt_ekf:=", what: "NDT's pose into ekf_global", values: "false (default), true" },
  { switch: "kiss_icp:=", what: "KISS-ICP lidar odometry, scored only", values: "false (default), true" },
  { switch: "kiss_ekf:=", what: "KISS-ICP's speed into ekf_local", values: "false (default), true" },
  { switch: "chase_camera:=", what: "Gazebo's camera behind the car", values: "true (default), false" },
];

export default function script(_event: Input<"/diagnostics">): Output {
  return { restart: "These need a restart: pixi run pick", switches };
}

ekf-poses.sourceCode:
// The EKFs' poses as arrows in the 3D view, over the car's roof: local blue, global green,
// as the debug HUD draws them. Lichtblick's 3D panel draws no nav_msgs/Odometry, so this
// turns each into a Marker. Each arrow sits where its EKF puts base_link.
import { Input, Messages } from "./types";

export const inputs = ["/localization/odom/local", "/localization/odom/global"];
export const output = "/studio_script/ekf_poses";

type Odom = Input<"/localization/odom/local"> | Input<"/localization/odom/global">;
const looks: { [topic: string]: { id: number; label: string; r: number; g: number; b: number } } = {
  "/localization/odom/local": { id: 0, label: "local EKF", r: 0.13, g: 0.59, b: 0.95 },
  "/localization/odom/global": { id: 1, label: "global EKF", r: 0.3, g: 0.69, b: 0.31 },
};
const last: { [topic: string]: any[] } = {};

function marker(header: any, id: number, type: number, pose: any, scale: any, color: any,
                text: string): any {
  return {
    header, ns: "ekf", id, type, action: 0, pose, scale, color, text,
    lifetime: { sec: 1, nsec: 0 }, frame_locked: false, points: [], colors: [],
    mesh_resource: "", mesh_use_embedded_materials: false,
  };
}

export default function script(event: Odom): Messages.visualization_msgs__MarkerArray {
  const look = looks[event.topic];
  const msg: any = event.message;
  const color = { r: look.r, g: look.g, b: look.b, a: 1 };
  const p = msg.pose.pose;
  // Lifted over the roof (2.2 m, 3 m for the label), or the car's model hides it.
  const arrow = { position: { x: p.position.x, y: p.position.y, z: p.position.z + 2.2 },
                  orientation: p.orientation };
  const label = { position: { x: p.position.x, y: p.position.y, z: p.position.z + 3.0 + look.id * 0.7 },
                  orientation: p.orientation };
  last[event.topic] = [
    marker(msg.header, look.id * 2, 0, arrow, { x: 2.5, y: 0.3, z: 0.3 }, color, ""),
    marker(msg.header, look.id * 2 + 1, 9, label, { x: 0, y: 0, z: 0.5 }, color, look.label),
  ];
  let markers: any[] = [];
  for (const topic of Object.keys(last)) {
    markers = markers.concat(last[topic]);
  }
  return { markers } as any;
}

ndt-scan.sourceCode:
// NDT's scan: the lidar scan placed where NDT puts the car, purple, over /map. Where it
// lies on the walls, NDT's fit is good; the cyan scan is the same scan where the EKF puts
// the car. Only while NDT runs (ndt:=true, test_lot).
import { Input, Messages } from "./types";

export const inputs = ["/localization/ndt/pose", "/sensors/lidar/scan"];
export const output = "/studio_script/ndt_scan";

type In = Input<"/localization/ndt/pose"> | Input<"/sensors/lidar/scan">;
let pose: any = undefined;

export default function script(event: In): Messages.visualization_msgs__Marker | undefined {
  if (event.topic === "/localization/ndt/pose") {
    pose = (event.message as any).pose.pose;
    return undefined;
  }
  if (pose === undefined) {
    return undefined;
  }
  const scan: any = event.message;
  const q = pose.orientation;
  const yaw = Math.atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z));
  const points: any[] = [];
  for (let i = 0; i < scan.ranges.length; i++) {
    const r = scan.ranges[i];
    if (!isFinite(r) || r < scan.range_min || r > scan.range_max) {
      continue;
    }
    // The scan is in base_link: turn it by NDT's yaw, move it to NDT's position.
    const a = scan.angle_min + i * scan.angle_increment + yaw;
    points.push({ x: pose.position.x + r * Math.cos(a), y: pose.position.y + r * Math.sin(a), z: 0.4 });
  }
  return {
    header: { stamp: scan.header.stamp, frame_id: "map" }, ns: "ndt_scan", id: 0, type: 8,
    action: 0, pose: { position: { x: 0, y: 0, z: 0 }, orientation: { x: 0, y: 0, z: 0, w: 1 } },
    scale: { x: 0.2, y: 0.2, z: 0 }, color: { r: 0.67, g: 0.28, b: 0.74, a: 1 },
    lifetime: { sec: 0, nsec: 300000000 }, frame_locked: false, points, colors: [], text: "",
    mesh_resource: "", mesh_use_embedded_materials: false,
  } as any;
}
